head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";
scwin.clickListBzDtlTpCd = "";
scwin.clickAdjReqProcsNo = "";

/************************************************************************************
 * ID           :	ULDSTF41611
 * File         :	ULDSTF41611.xml
 * Name         :	(팝업)파이프라인 진행 경과 수정처리
 * Author       :	배성우
 * Description  :
 * Create Date  :	2026-06-26
 ************************************************************************************/

// scwin.pMenuID = $c.stf.infoMenuID();
// let fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
// scwin.fr_MktId = $c.lc.getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
// scwin.fn_GetPar, scwin.fn_SetPar;
// dialog 호출용 함수
// 발행기관목록관련

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41611.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_list_oncelldblclick
 * @description 수정승인, 수정불가 더블클릭
 * @param {Number} row 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} colid 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_oncelldblclick = async function (row, columnIndex, colid) {
    try {
        scwin.setBzProcsNo(row);
        if ("funcAcpt" === colid) {
            let vAnswer = await $c.win.confirm($c.data.getMessage("com_crud_0198", "승인"));
            if (vAnswer === true) {
                await scwin.trs("35");
            }
        } else if ("funcRjct" === colid) {
            let vAnswer = await $c.win.confirm($c.data.getMessage("com_crud_0198", "불가"));
            if (vAnswer === true) {
                await scwin.trs("36");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41611.grd_list_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {
    let reqMap = {
        bzProcsNo: scwin.vBzProcsNo, // 업무처리번호
        listInvstgBzTpCd: scwin.vListBzTpCd, // 상장심사업무구분코드
    };
    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/lstmgt/pipelineprog-adjreq/select-list",
        method: "get",
        target: "dlt_selectList=body",
        // submitDoneHandler : scwin.sbm_selectList_submitdone,
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions, reqMap);
};

/**
 * @method
 * @name trs
 * @description 트랜잭션 객체 처리(레거시).
 * @param {String} listProcsStatCd 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function (listProcsStatCd) {
    let reqMap = {
        listProcsStatCd: listProcsStatCd, // 상장처리상태코드
        bzProcsNo: scwin.vBzProcsNo, // 업무처리번호
        listBzTpCd: scwin.vListBzTpCd, // 상장업무구분코드
        listBzDtlTpCd: scwin.clickListBzDtlTpCd, // 상장업무상세구분코드
        adjReqProcsNo: scwin.clickAdjReqProcsNo, // 수정요청 업무처리번호
    };
    const sbmOptions = {
        id: "sbm_processPipelineprog",
        action: "/api/listing/lstmgt/pipelineprog-adjreq/process-pipelineprog",
        method: "post",
        // target : "dlt_selectList=body",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        if (listProcsStatCd === "35") {
            await $c.win.alert($c.data.getMessage("com_complete_0150", "수정승인"));
        } else {
            await $c.win.alert($c.data.getMessage("com_complete_0150", "수정불가"));
        }
        $c.win.closePopup();
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    // let parentWin = $c.win.getParent();
    const parentWin = $c.data.getParameter();
    scwin.vBzProcsNo = parentWin.vBzProcsNo;
    scwin.vListBzTpCd = "230";
    scwin.listSync();
}

/**
 * @method
 * @name setBzProcsNo
 * @description 업무처리번호를 화면 상태값에 설정한다.
 * @param {Object} obj 객체
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function (obj) {
    scwin.clickListBzDtlTpCd = dlt_selectList.getCellData(obj, "listBzDtlTpCd");
    scwin.clickAdjReqProcsNo = dlt_selectList.getCellData(obj, "adjReqProcsNo");
};
